Definition x2_cellbytes (c : deltX2) : list byte :=
  [Z_to_bv 8 (x2_seq c); Z_to_bv 8 (x2_seq c / 256); Z_to_bv 8 (x2_nbBits c); Z_to_bv 8 (x2_len c)].
Definition x2_bytes' (cells : list deltX2) : list byte := concat (map x2_cellbytes cells).

