(* [comment removed for export] *)
Lemma x2_cell_rd : forall segs m A cells k v c, bytes_at segs m A (firstn k (x2_bytes' cells)) ->
  0 <= v -> 4 * v + 4 <= Z.of_nat k -> v < Z.of_nat (length cells) -> c = nth (Z.to_nat v) cells x2_default ->
  0 <= x2_seq c < 65536 ->
  ov_read_bytes segs m (Z_to_bv 64 (A + 4 * v)) 2 = Some (le2 (Z_to_bv 64 (x2_seq c)))
  /\ ov_read_bytes segs m (Z_to_bv 64 (A + 4 * v + 2)) 1 = Some [Z_to_bv 8 (x2_nbBits c)]
  /\ ov_read_bytes segs m (Z_to_bv 64 (A + 4 * v + 3)) 1 = Some [Z_to_bv 8 (x2_len c)]
  /\ ov_read_bytes segs m (Z_to_bv 64 (A + 4 * v)) 1 = Some [Z_to_bv 8 (x2_seq c)].
Proof.
